import difflib,json,sys
from pathlib import Path
sys.path[:0]=['src','tests']
from company_wiki.automation.narrative_model_runtime import build_model_request
from company_wiki.automation.narrative_contracts import NarrativeSelectResult
r=json.loads(Path('tests/fixtures/atomic_recipe_legacy_requests.json').read_text(encoding='utf-8'))
def diff(x,y,path=''):
 if isinstance(x,dict) and isinstance(y,dict):
  for k in x.keys()|y.keys():
   if k not in x or k not in y:print(path+'/'+k,x.get(k),y.get(k))
   else:diff(x[k],y[k],path+'/'+k)
 elif x!=y:print(path,repr(x)[:100],repr(y)[:100])
for v in ['reading-model-input/4','reading-model-input/6']:
 current=build_model_request(NarrativeSelectResult.from_dict(r['selection']),reading_projection_version=v)
 old=r['requests'][v]
 print(v)
 print('\n'.join(x for x in difflib.ndiff(old['instruction'].split('. '),current.instruction.split('. ')) if not x.startswith('  ')))
 diff(json.loads(old['data_json']),json.loads(current.data_json))
